pub fn decode_frames(data: &[u8]) -> Option<Vec<Vec<u8>>> {
    if data.is_empty() {
        return Some(vec![]);
    }

    let mut frames: Vec<Vec<u8>> = Vec::new();
    let mut i = 0;

    while i < data.len() {
        // Check for valid length byte (0-255)
        if data[i] > 255 {
            return None;
        }

        let n = data[i] as usize;
        if n == 0 {
            // Check for trailing partial data (length 0 means no payload)
            if i + 1 < data.len() {
                // Check for valid checksum byte
                let checksum = data[i + 1];
                if checksum > 255 {
                    return None;
                }
                // Verify checksum: sum of payload bytes modulo 256
                let payload_sum: u8 = frames.iter().map(|b| *b).sum();
                if payload_sum % 256 != checksum {
                    return None;
                }
            }
            i += 1;
            continue;
        }

        // Check for valid payload bytes
        if n > data.len() - i {
            return None;
        }

        let payload = &data[i..i + n];
        frames.push(payload.to_vec());

        // Move past payload and checksum
        i += n + 1;
    }

    Some(frames)
}

